def backfill_legacy_waivers(apps, schema_editor):
    RentCharge = apps.get_model("rent", "RentCharge")
    ObligationAdjustment = apps.get_model("rent", "ObligationAdjustment")
    for charge in RentCharge.objects.filter(status="waived").iterator():
        remaining = max((charge.amount_minor or 0) - (charge.amount_paid_minor or 0), 0)
        if not remaining:
            continue
        ObligationAdjustment.objects.create(
            obligation_id=charge.id,
            kind="waiver",
            amount_minor=remaining,
            amount_currency=charge.amount_currency or "GHS",
            reason=charge.waived_reason or "Legacy full-balance waiver",
            actor_id=None,
            effective_at=charge.settled_at or charge.updated_at or timezone.now(),
        )


